import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy device checks","description":"October 23 alignment: Cryptita Plays community beta testing is November 10, 2026; pre-final is November 21. Test the adopted W01–W04 and B01–B03/demo B07 core. Wordle/BlockMat","frontmatter":{"title":"Chainy device checks","description":"October 23 alignment: Cryptita Plays community beta testing is November 10, 2026; pre-final is November 21. Test the adopted W01–W04 and B01–B03/demo B07 core. Wordle/BlockMat","source":"docs/hardware-validation.md","category":"Research & evaluation","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/hardware-validation.md","filePath":"content/docs/hardware-validation.md"}'),o={name:"content/docs/hardware-validation.md"};function n(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-device-checks">Chainy device checks<a class="header-anchor" href="#chainy-device-checks" aria-label="Link to this section">​</a></h1><p>October 23 alignment: Cryptita Plays community beta testing is November 10, 2026; pre-final is November 21. Test the adopted W01–W04 and B01–B03/demo B07 core. Wordle/BlockMatch and later teacher services are not beta acceptance blockers. Protect integration/device tests through November 6 and regression/rehearsal November 7–9.</p><p>Owners: Christian executes technical checks, Miguel checks UI, Luis checks art/import cost. Updated October 23, 2026.</p><h2 id="retained-target-specification">Retained target specification<a class="header-anchor" href="#retained-target-specification" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Item</th><th>Target / interpretation</th></tr></thead><tbody><tr><td>Android</td><td>User-supplied 10+/11+; 11+ provisional test baseline, 10 compatibility candidate</td></tr><tr><td>RAM</td><td>4 GB physical RAM</td></tr><tr><td>Storage</td><td>64 GB total device capacity; this is not the game&#39;s required space</td></tr><tr><td>CPU</td><td>ARM64</td></tr><tr><td>Graphics</td><td>OpenGL ES 3.2 or Vulkan 1.1</td></tr><tr><td>GPU</td><td>Entry-level-to-midrange target class; actual device must be named</td></tr></tbody></table><p>The supplied design uses Unity, but the exact version, render pipeline, SQLite binding and tested phones are not supplied. Christian records these on CH-03/04. Engine/editor success is not evidence of Android support.</p><h2 id="test-the-actual-game">Test the actual game<a class="header-anchor" href="#test-the-actual-game" aria-label="Link to this section">​</a></h2><p>Install the build on a representative phone. Test movement/collision, dialogue, scene switching, W01–W04, B01–B03/demo B07, contextual Quiz and local profile/save/reload in airplane mode. Teacher services and standalone modes are later checks, not beta prerequisites.</p><p>Record the phone model, Android version, build/revision, free space, graphics path, visible stalls, memory/performance readings where available, load/save times and any overheating or crash. Test a complete expected beta session, not only an empty scene.</p><p>Recommendation: aim for steady 30 FPS initially and review readable controls on the smallest target display. This is a proposed target, not measured performance. Set additional budgets only when the representative level provides useful measurements.</p><p>If performance fails, reduce unnecessary scenery, expensive effects and texture size before changing the learning rules. Test the existing player controller&#39;s speed, rotation and collision on the phone even though it is reported completed.</p><h2 id="required-handoff">Required handoff<a class="header-anchor" href="#required-handoff" aria-label="Link to this section">​</a></h2><p>CH-03: reproducible installed APK and source/build instructions. CH-04: two local profiles, saved result reload and failure recovery. CH-14: W01–W04 and B01–B03/demo B07, atomic economy/quest saving, interrupted play and signed update on the beta devices. Verify any approved minimal collection path separately; standalone modes and the broad teacher platform are later scope.</p><p><strong>Cryptita Plays community beta November 10; pre-final November 21, 2026.</strong> Integration/device readiness checks are planned for October 31–November 6, followed by regression/rehearsal November 7–9. No supported-device claim is made until these checks pass.</p></div>',1)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
